def normalize(source):
    if hashlib.sha256(source.encode()).hexdigest() != CANDIDATE:
        raise AssertionError('Ordered identity historical boundary source changed')
    for added, prior in BLOCKS:
        if source.count(added) != 1:
            raise AssertionError('Ordered identity exact extension boundary changed')
        source = source.replace(added, prior, 1)
    if hashlib.sha256(source.encode()).hexdigest() != PRIOR:
        raise AssertionError('Ordered identity normalization changed an unrelated guard')
    return source
